export default "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>무궁화 꽃이 피었습니다 · 서린태권도</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Black+Han+Sans&family=IBM+Plex+Sans+KR:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --blue:#0B3C9C; --blue-deep:#06235E; --sky:#4C9BFF; --red:#E8302A; --gold:#FFC93C;\n  --paper:#F3F7FF; --ink:#0E1A33; --panel:rgba(243,247,255,.94); --panel-ink:#0E1A33; --line:rgba(11,60,156,.18);\n  box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px); padding-bottom:env(safe-area-inset-bottom,0px);\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){ --panel:rgba(8,20,48,.92); --panel-ink:#EAF1FF; --line:rgba(140,180,255,.22); }\n}\n:root[data-theme=\"dark\"]{ --panel:rgba(8,20,48,.92); --panel-ink:#EAF1FF; --line:rgba(140,180,255,.22); }\n\n*,*::before,*::after{box-sizing:inherit}\nhtml,body{height:100%;margin:0}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\nbody{background:var(--blue-deep);color:#fff;font-family:\"IBM Plex Sans KR\",\"Apple SD Gothic Neo\",\"Malgun Gothic\",sans-serif;overflow:hidden}\n#stage{position:relative;height:100%;width:100%;overflow:hidden}\ncanvas#view{position:absolute;inset:0;width:100%;height:100%;display:block}\n#tint{position:absolute;inset:0;pointer-events:none;transition:background .25s}\n.phase-go #tint{background:linear-gradient(180deg,rgba(11,60,156,.55),rgba(11,60,156,.05) 45%)}\n.phase-stop #tint,.phase-watch #tint{background:linear-gradient(180deg,rgba(232,48,42,.6),rgba(232,48,42,.08) 45%);box-shadow:inset 0 0 0 10px var(--red)}\n.phase-pass #tint{background:linear-gradient(180deg,rgba(255,201,60,.55),transparent 45%)}\n\n#chant{position:absolute;left:0;right:0;top:clamp(16px,4vh,48px);display:flex;justify-content:center;gap:clamp(2px,.6vw,10px);flex-wrap:wrap;padding:0 16px;pointer-events:none}\n#chant span{font-family:\"Black Han Sans\",\"IBM Plex Sans KR\",sans-serif;font-size:clamp(36px,8.5vw,128px);line-height:1;color:rgba(255,255,255,.22);transition:color .08s, transform .08s;text-shadow:0 4px 18px rgba(0,0,0,.35)}\n#chant span.on{color:#fff;transform:translateY(-6px)}\n#chant span.gap{width:clamp(10px,2vw,30px)}\n\n#big{position:absolute;left:0;right:0;top:50%;transform:translateY(-50%);text-align:center;pointer-events:none;font-family:\"Black Han Sans\",sans-serif;font-size:clamp(72px,18vw,260px);line-height:1;letter-spacing:.02em;opacity:0;text-shadow:0 8px 40px rgba(0,0,0,.45)}\n#big.show{opacity:1;animation:pop .35s ease-out}\n@keyframes pop{from{transform:translateY(-50%) scale(1.25)}to{transform:translateY(-50%) scale(1)}}\n#timer{position:absolute;left:24px;right:24px;bottom:calc(110px + env(safe-area-inset-bottom,0px));height:14px;border-radius:7px;background:rgba(255,255,255,.2);overflow:hidden;opacity:0;transition:opacity .2s}\n#timer.show{opacity:1}\n#timer i{display:block;height:100%;width:100%;background:#fff;transform-origin:left;}\n\n#hud{position:absolute;top:calc(env(safe-area-inset-top,0px) + 12px);right:16px;font-weight:700;font-size:clamp(14px,1.6vw,20px);background:rgba(6,35,94,.6);padding:6px 14px;border-radius:999px;display:none}\n.playing #hud{display:block}\n\n/* 게임 시작·설정 바: 대기 중엔 위, 게임 중(멈추기 버튼만)엔 아래 */\n#bar{position:absolute;left:0;right:0;top:0;zoom:var(--tvz,1);padding:calc(14px + env(safe-area-inset-top,0px)) 16px 14px;display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap;background:linear-gradient(180deg,rgba(6,35,94,.85),transparent)}\n.playing #bar{top:auto;bottom:0;padding:14px 16px calc(14px + env(safe-area-inset-bottom,0px));background:linear-gradient(0deg,rgba(6,35,94,.6),transparent)}\nbutton{font:inherit;font-weight:700;border:0;border-radius:14px;padding:14px 26px;font-size:clamp(16px,1.7vw,22px);cursor:pointer;color:#fff;background:var(--blue);box-shadow:0 4px 0 var(--blue-deep)}\nbutton:active{transform:translateY(2px);box-shadow:0 2px 0 var(--blue-deep)}\nbutton.ghost{background:rgba(255,255,255,.14);box-shadow:none}\nbutton.red{background:var(--red);box-shadow:0 4px 0 #8f1410}\nbutton:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:2px}\n\n#settings{position:absolute;z-index:6;zoom:var(--tvz,1);right:16px;top:calc(var(--barH,84px) + 4px);width:min(360px,calc(100% - 32px));background:var(--panel);color:var(--panel-ink);border-radius:18px;padding:18px 20px;display:none;max-height:calc(100% - var(--barH,84px) - 20px);overflow:auto;box-shadow:0 20px 50px rgba(0,0,0,.35)}\n#settings.open{display:block}\n#settings h3{margin:0 0 12px;font-size:18px}\n.row{margin:0 0 16px}\n.row label{display:flex;justify-content:space-between;font-weight:600;font-size:15px;margin-bottom:6px}\n.row small{display:block;opacity:.7;font-size:13px;margin-top:4px;line-height:1.45}\ninput[type=range]{width:100%;accent-color:var(--blue)}\nselect{width:100%;font:inherit;padding:8px 10px;border-radius:10px;border:1px solid var(--line);background:transparent;color:inherit}\nselect option{color:#0E1A33}\n.check{display:flex;gap:8px;align-items:center;font-weight:600;font-size:15px}\n\n#intro,#caught,#err{position:absolute;inset:0;display:none;align-items:center;justify-content:center;padding:24px}\n#intro.show,#caught.show,#err.show{display:flex}\n#intro{background:var(--blue-deep)}\n.card{max-width:560px;text-align:center}\n.card h1{font-family:\"Black Han Sans\",sans-serif;font-weight:400;font-size:clamp(44px,8vw,88px);line-height:1.05;margin:0 0 18px}\n.card p{font-size:clamp(16px,1.8vw,20px);line-height:1.65;margin:0 0 10px;color:#CFE0FF}\n.card .by{margin-top:28px;font-size:14px;color:#7FA6E8;letter-spacing:.04em}\n.card button{margin-top:22px}\n#caught{align-items:flex-end;pointer-events:none}\n#caught .box{pointer-events:auto;background:rgba(232,48,42,.95);border-radius:22px;padding:18px 26px;text-align:center;margin-bottom:calc(90px + env(safe-area-inset-bottom,0px));box-shadow:0 18px 50px rgba(0,0,0,.4)}\n#caught .box b{display:block;font-family:\"Black Han Sans\",sans-serif;font-weight:400;font-size:clamp(34px,6vw,64px);line-height:1.1}\n#caught .box span{display:block;margin:6px 0 12px;font-size:clamp(15px,1.6vw,19px)}\n#caught .box button{background:#fff;color:var(--red);box-shadow:0 4px 0 rgba(0,0,0,.25);margin:4px}\n@media (prefers-reduced-motion: reduce){#big.show{animation:none}#chant span{transition:none}}\n.card,#caught .box{zoom:var(--tvz,1)}\n</style>\n<script>\n// 모든 게임 공통 카메라: 한 번 고른 카메라(slg-cam)를 모든 게임이 같이 씀 → 없으면 후면 카메라 우선\nconst slgLS={get(k){try{return localStorage.getItem(k)}catch(e){return null}},set(k,v){try{v==null?localStorage.removeItem(k):localStorage.setItem(k,v)}catch(e){}}};\nasync function slgOpenCam(deviceId,w,h,facing){\n  // 휴대폰·PC·TV 어디서든 켜지게: 기억한 카메라 → 후면 → 아무 카메라 → 가장 단순한 요청 → 남은 카메라 하나씩\n  const md=navigator.mediaDevices, old=navigator.getUserMedia||navigator.webkitGetUserMedia||navigator.mozGetUserMedia;\n  const gum=v=>md&&md.getUserMedia?md.getUserMedia({audio:false,video:v})\n    :old?new Promise((ok,no)=>old.call(navigator,{audio:false,video:v},ok,no)):Promise.reject({name:'NotFoundError'}); // 옛날 TV 브라우저용\n  const size={width:{ideal:w},height:{ideal:h}}, saved=deviceId||slgLS.get('slg-cam'), tries=[];\n  if(saved) tries.push({deviceId:{exact:saved},...size});\n  tries.push({facingMode:{ideal:facing||'environment'},...size}, size, true);\n  let err;\n  for(const v of tries){\n    try{ const s=await gum(v); if(deviceId&&v===tries[0]) slgLS.set('slg-cam',deviceId); return s; }\n    catch(e){ err=e; if(e&&(e.name==='NotAllowedError'||e.name==='SecurityError')) throw e; // 권한 거절이면 더 묻지 않음\n      if(saved&&v===tries[0]&&!deviceId) slgLS.set('slg-cam',null); } // 기억한 카메라가 빠졌으면 잊음\n  }\n  try{ for(const d of (await md.enumerateDevices()).filter(d=>d.kind==='videoinput')) try{ return await gum({deviceId:{exact:d.deviceId}}); }catch(e){} }catch(e){} // 다른 프로그램이 쓰는 카메라는 건너뜀\n  throw err;\n}\nconst slgSet=s=>{ const t=s&&s.getVideoTracks()[0]; return t&&t.getSettings?t.getSettings():{}; }; // 지금 켜진 카메라 정보 (옛 브라우저는 빈 값)\nasync function slgCams(){ try{ return (await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput'); }catch(e){ return []; } }\n</script>\n<script>\n// 음성 인식: 홈 화면이 하나만 계속 켜 두고 들린 말을 나눠 줌 → 게임을 옮겨도 끊기지 않고 시작하자마자 들림\n// (마이크 고르기·권한 허용은 홈 화면 [🎥 카메라 · 마이크]에서)\ntry{ if(parent!==window&&parent.SlgSR) window.SpeechRecognition=window.webkitSpeechRecognition=parent.SlgSR; }catch(e){}\nfunction slgRecStart(rec){ (window.slgRecs=window.slgRecs||new Set).add(rec);\n  if(!rec.slgW){ rec.slgW=1; const h=rec.onresult; // slgFresh 순간에 말하던 문장만 건너뛰고 나머지는 게임에 넘김\n    rec.addEventListener('start',()=>{ rec.slgMark=rec.slgLast=null; }); // 새로 켜지면 하던 말은 끝난 것\n    rec.onresult=e=>{\n      const n=e.results.length, r=e.results[n-1], m=rec.slgMark; rec.slgLast=r&&{i:n-1,t:r[0].transcript,f:r.isFinal};\n      if(m){ const x=e.results[m.i]; // 번호가 아니라 내용으로 같은 문장인지 봄 (안드로이드는 새 말도 같은 번호로 보냄)\n        if(x&&e.resultIndex<=m.i&&slgSame(x[0].transcript,m.t)){ if(x.isFinal) rec.slgMark=null; Object.defineProperty(e,'resultIndex',{value:m.i+1}); }\n        else rec.slgMark=null; }\n      if(e.resultIndex<n&&h) h(e); }; }\n  try{ rec.start(); }catch(e){} } // 이미 듣는 중이면 무시\nconst slgSame=(a,b)=>{ a=String(a).replace(/\\s/g,''); b=String(b).replace(/\\s/g,''); return a.startsWith(b)||b.startsWith(a); };\nfunction slgFresh(rec){ if(rec) rec.slgMark=rec.slgLast&&!rec.slgLast.f?{i:rec.slgLast.i,t:rec.slgLast.t}:null; } // 카운터 시작 순간: 그때 말하던 문장(\"시작\" 등)만 버림\nconst slgRecMsg=e=>({'not-allowed':'마이크 권한이 없어요. 홈 화면에서 [한 번에 허용하기]를 눌러 주세요','service-not-allowed':'이 브라우저는 음성 인식을 막고 있어요. 크롬이나 엣지로 열어 주세요',\n  'audio-capture':'마이크를 찾지 못했어요. 블루투스 마이크라면 기기의 기본 마이크로 연결돼 있는지 확인해 주세요','network':'음성 인식은 인터넷 연결이 필요해요'})[e.error]||'';\n// \"시작\"이라고 말하면 시작\nconst slgSaidStart=t=>/시작|스타트|start/i.test(String(t).replace(/\\s/g,''));\nfunction slgVoiceStart(fn){ // 음성 인식을 따로 안 쓰는 게임용: 계속 듣다가 \"시작\"이 들리면 fn()\n  const SR=window.SpeechRecognition||window.webkitSpeechRecognition; if(!SR) return;\n  const rec=new SR(); rec.lang='ko-KR'; rec.continuous=true; rec.interimResults=true; let on=true, last=0;\n  rec.onresult=e=>{ for(let i=e.resultIndex;i<e.results.length;i++) if(slgSaidStart(e.results[i][0].transcript)&&Date.now()-last>3000){ last=Date.now(); fn(); } };\n  rec.onerror=e=>{ if(e.error==='not-allowed'||e.error==='service-not-allowed') on=false; };\n  rec.onend=()=>{ if(on) setTimeout(()=>slgRecStart(rec),300); }; // 조용하면 끊기므로 다시 켬\n  slgRecStart(rec);\n}\n</script>\n<script>\n// 전체 화면 켜기/끄기 (게임 공통). 아이폰처럼 지원 안 하는 기기는 안내\nconst SLG_NOFULL='이 기기(아이폰 등)는 브라우저 전체 화면을 지원하지 않아요. 공유 버튼 → 「홈 화면에 추가」로 열면 화면을 꽉 채워요.';\nfunction slgToggleFull(){\n  const d=document, el=d.documentElement, cur=d.fullscreenElement||d.webkitFullscreenElement, rq=el.requestFullscreen||el.webkitRequestFullscreen;\n  try{ const p=cur?(d.exitFullscreen||d.webkitExitFullscreen).call(d):rq?rq.call(el):(alert(SLG_NOFULL),null); p&&p.catch&&p.catch(()=>{}); }catch(e){}\n}\n</script>\n</head>\n<body>\n<div id=\"stage\" class=\"phase-idle\">\n  <canvas id=\"view\"></canvas>\n  <div id=\"tint\"></div>\n  <div id=\"chant\"></div>\n  <div id=\"big\"></div>\n  <div id=\"timer\"><i></i></div>\n  <div id=\"hud\">통과한 라운드 <span id=\"round\">0</span> · 속도 <span id=\"rateV\">1.0배</span></div>\n\n  <div id=\"bar\">\n    <button id=\"startBtn\">게임 시작</button>\n    <button id=\"stopBtn\" class=\"ghost\" hidden>멈추기</button>\n    <button id=\"fsBtn\" class=\"ghost\">전체 화면</button>\n    <button id=\"setBtn\" class=\"ghost\" aria-expanded=\"false\" aria-controls=\"settings\">설정</button>\n  </div>\n\n  <div id=\"settings\" role=\"dialog\" aria-label=\"게임 설정\">\n    <h3>게임 설정</h3>\n    <div class=\"row\">\n      <label for=\"speed\">무궁화 음원 속도</label>\n      <select id=\"speed\">\n        <option value=\"random\" selected>랜덤 (20가지 박자)</option>\n        <option value=\"normal\">보통</option>\n        <option value=\"fast\">빠르게</option>\n      </select>\n    </div>\n    <div class=\"row\">\n      <label for=\"rate\">실시간 속도 조절 <span id=\"rateV2\">1.0배</span></label>\n      <input id=\"rate\" type=\"range\" min=\"0.5\" max=\"2\" step=\"0.1\" value=\"1\">\n      <small>게임 중에도 바로 적용됩니다. 키보드 ↑ ↓ 키로도 조절할 수 있어요.</small>\n    </div>\n    <div class=\"row\">\n      <label for=\"sens\">감지 민감도 <span id=\"sensV\">레벨 5</span></label>\n      <input id=\"sens\" type=\"range\" min=\"1\" max=\"10\" value=\"5\">\n      <small>레벨이 높을수록 작은 움직임도 잡아냅니다. 저학년은 레벨 4~5, 고학년·유단자는 레벨 7~8을 추천합니다.</small>\n    </div>\n    <div class=\"row\">\n      <label for=\"dist\">카메라와 거리</label>\n      <select id=\"dist\"><option value=\"1\">가까이 (2~3m)</option><option value=\"2\">멀리 (약 5m)</option><option value=\"3\">아주 멀리 (약 10m)</option></select>\n      <small>아이들이 서 있는 거리에 맞추세요. 멀수록 작은 움직임도 잡도록 감지를 맞춥니다.</small>\n    </div>\n    <div class=\"row\">\n      <label for=\"hold\">멈춰 있는 시간 <span id=\"holdV\">3초</span></label>\n      <input id=\"hold\" type=\"range\" min=\"2\" max=\"8\" value=\"3\">\n    </div>\n    <div class=\"row\">\n      <label for=\"cam\">카메라</label>\n      <select id=\"cam\"></select>\n    </div>\n    <div class=\"row\">\n      <label class=\"check\"><input id=\"sound\" type=\"checkbox\" checked> 효과음과 음성</label>\n    </div>\n    <div class=\"row\">\n      <label class=\"check\"><input id=\"mirror\" type=\"checkbox\" checked> 거울처럼 좌우 반전</label>\n    </div>\n  </div>\n\n  <div id=\"intro\" class=\"show\">\n    <div class=\"card\">\n      <h1>무궁화 꽃이<br>피었습니다</h1>\n      <p>글자가 나오는 동안에는 카메라 쪽으로 다가오세요.</p>\n      <p>화면이 빨갛게 변하면 그대로 멈춰야 해요.<br>카메라가 움직인 사람을 찾아냅니다.</p>\n      <button id=\"camBtn\">카메라 켜기</button>\n      <div class=\"by\">SEOLIN TAEKWONDO</div>\n    </div>\n  </div>\n\n  <div id=\"caught\">\n    <div class=\"box\">\n      <b>움직였어요!</b>\n      <span>빨간 네모 안에 있는 친구가 탈락입니다.</span>\n      <button id=\"contBtn\">계속하기</button>\n      <button id=\"resetBtn\">처음부터</button>\n    </div>\n  </div>\n\n  <div id=\"err\">\n    <div class=\"card\">\n      <h1 style=\"font-size:clamp(34px,5vw,56px)\">카메라를 켤 수 없어요</h1>\n      <p id=\"errMsg\">브라우저 주소창 옆의 카메라 권한을 허용한 뒤 다시 눌러 주세요.</p>\n      <button id=\"retryBtn\">다시 시도</button>\n    </div>\n  </div>\n</div>\n\n<video id=\"video\" playsinline muted autoplay style=\"display:none\"></video>\n\n<script>\n(() => {\n  const $ = id => document.getElementById(id);\n  const stage=$('stage'), view=$('view'), vctx=view.getContext('2d');\n  const video=$('video'), chantEl=$('chant'), big=$('big'), timer=$('timer'), timerBar=timer.querySelector('i');\n  const SYL=['무','궁','화','_','꽃','이','_','피','었','습','니','다'];\n  // mugunghwa.mp3 안에서 각 글자가 시작되는 시각(초). 어긋나면 이 숫자만 고치면 됨\n  // (음높이·자음 소리 분석 기준: 무 궁 화 꽃 이 피 었 습 니 다)\n  const TIMES=[0.18,0.44,0.80,1.46,2.18,2.84,3.22,3.42,3.84,4.14], CHANT_END=4.6;\n  const bgm=new Audio('data:audio/mpeg;base64,'); bgm.preload='auto';\n\n  // chant letters\n  const spans=[];\n  SYL.forEach(s=>{const e=document.createElement('span'); if(s==='_'){e.className='gap';} else {e.textContent=s; spans.push(e);} chantEl.appendChild(e);});\n\n  // detection buffer\n  let SW=128, SH=72;\n  const small=document.createElement('canvas'); const sctx=small.getContext('2d',{willReadFrequently:true});\n  let ref=null, hits=null, cols=16, rows=9;\n\n  let stream=null, phase='idle', round=0, running=false, timers=[], crop={sx:0,sy:0,sw:1,sh:1};\n  let flagged=[], frozen=false, watchUntil=0, watchStart=0;\n\n  // settings\n  const sens=$('sens'), hold=$('hold');\n  const dist=$('dist'); dist.value=slgLS.get('mugunghwa-dist')||'3'; const K=()=>+dist.value; // 거리 배율: 1=2~3m, 2=약 5m, 3=약 10m\n  dist.onchange=()=>{ slgLS.set('mugunghwa-dist',dist.value); ref=null; };\n  sens.oninput=()=>$('sensV').textContent='레벨 '+sens.value;\n  // 실시간 속도: 박자 패턴 속도(curRate)에 곱해서 바로 적용\n  const rateIn=$('rate'); let userRate=1, curRate=1;\n  const applyRate=()=>{ bgm.playbackRate=Math.min(MAX_RATE,curRate*userRate); };\n  rateIn.oninput=()=>{ userRate=+rateIn.value; $('rateV').textContent=$('rateV2').textContent=userRate.toFixed(1)+'배'; applyRate(); };\n  hold.oninput=()=>$('holdV').textContent=hold.value+'초';\n  $('setBtn').onclick=()=>{const o=$('settings').classList.toggle('open'); $('setBtn').setAttribute('aria-expanded',o);};\n  $('mirror').onchange=()=>{ref=null;};\n\n  // audio\n  let actx=null;\n  function tone(freq,dur=.18,type='triangle',vol=.25){\n    if(!$('sound').checked||!freq) return;\n    try{ actx=actx||new (window.AudioContext||window.webkitAudioContext)();\n      const o=actx.createOscillator(), g=actx.createGain(); o.type=type; o.frequency.value=freq;\n      g.gain.setValueAtTime(vol,actx.currentTime); g.gain.exponentialRampToValueAtTime(.001,actx.currentTime+dur);\n      o.connect(g).connect(actx.destination); o.start(); o.stop(actx.currentTime+dur);\n    }catch(e){}\n  }\n  function say(t){ if(!$('sound').checked||!window.speechSynthesis) return; try{speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(t); u.lang='ko-KR'; u.rate=1.1; speechSynthesis.speak(u);}catch(e){} }\n\n  // camera\n  async function listCams(){\n    try{ const devs=await slgCams();\n      const sel=$('cam'), cur=stream&&slgSet(stream).deviceId;\n      sel.innerHTML=''; devs.forEach((d,i)=>{const o=document.createElement('option'); o.value=d.deviceId; o.textContent=d.label||('카메라 '+(i+1)); if(d.deviceId===cur)o.selected=true; sel.appendChild(o);});\n    }catch(e){}\n  }\n  async function startCam(deviceId){\n    if(stream) stream.getTracks().forEach(t=>t.stop());\n    stream=await slgOpenCam(deviceId,1920,1080); // 10m 앞 사람도 보이게 고화질\n    const fm=slgSet(stream).facingMode; if(fm) $('mirror').checked=fm==='user'; // 전면은 거울처럼, 후면은 그대로\n    video.srcObject=stream; await video.play().catch(()=>{}); ref=null; listCams();\n  }\n  $('cam').onchange=e=>startCam(e.target.value).catch(showErr);\n  function showErr(e){ $('err').classList.add('show'); $('intro').classList.remove('show');\n    if(e&&e.name==='NotFoundError') $('errMsg').textContent='연결된 카메라를 찾지 못했습니다. 웹캠을 연결한 뒤 다시 눌러 주세요.';\n    else if(e&&e.name==='NotAllowedError') $('errMsg').textContent='카메라 권한이 막혀 있습니다. 주소창 옆 자물쇠 아이콘에서 카메라를 허용한 뒤 다시 눌러 주세요.';\n  }\n  async function boot(){\n    try{ await startCam(); keepAwake(); $('intro').classList.remove('show'); $('err').classList.remove('show'); requestAnimationFrame(loop);}catch(e){showErr(e);}\n  }\n  $('camBtn').onclick=boot; $('retryBtn').onclick=boot;\n  boot(); // 들어오자마자 카메라 켜기\n\n  // 휴대폰 → TV 미러링용: 전체 화면 + 가로 고정 + 화면 꺼짐 방지\n  const root=document.documentElement, fsReq=root.requestFullscreen||root.webkitRequestFullscreen;\n  $('fsBtn').onclick=()=>{\n    const d=document;\n    if(d.fullscreenElement||d.webkitFullscreenElement) (d.exitFullscreen||d.webkitExitFullscreen).call(d);\n    else if(!fsReq) alert(SLG_NOFULL); // 아이폰 등\n    else Promise.resolve(fsReq.call(root)).then(()=>screen.orientation&&screen.orientation.lock&&screen.orientation.lock('landscape')).catch(()=>{});\n  };\n  const keepAwake=()=>{ try{ navigator.wakeLock&&navigator.wakeLock.request('screen').catch(()=>{}); }catch(e){} };\n  document.addEventListener('visibilitychange',()=>{ if(document.visibilityState==='visible'&&stream) keepAwake(); });\n\n  // render loop\n  function fit(){\n    const dpr=Math.min(window.devicePixelRatio||1,2), w=view.clientWidth, h=view.clientHeight;\n    if(view.width!==Math.round(w*dpr)||view.height!==Math.round(h*dpr)){view.width=Math.round(w*dpr);view.height=Math.round(h*dpr);ref=null;}\n    const vw=video.videoWidth, vh=video.videoHeight; if(!vw) return false;\n    const ar=view.width/view.height, va=vw/vh;\n    if(va>ar){crop.sh=vh;crop.sw=vh*ar;crop.sx=(vw-crop.sw)/2;crop.sy=0;} else {crop.sw=vw;crop.sh=vw/ar;crop.sx=0;crop.sy=(vh-crop.sh)/2;}\n    SW=128*K(); cols=16*K(); const nh=Math.max(36,Math.round(SW/ar)); // 멀수록 칸을 잘게 나눠서 작게 보이는 사람의 움직임도 잡음 if(nh!==SH||small.width!==SW){SH=nh; small.width=SW; small.height=SH; ref=null; rows=Math.max(6,Math.round(cols/ar));}\n    return true;\n  }\n  function drawVideo(ctx,w,h){\n    ctx.save(); if($('mirror').checked){ctx.translate(w,0);ctx.scale(-1,1);}\n    ctx.drawImage(video,crop.sx,crop.sy,crop.sw,crop.sh,0,0,w,h); ctx.restore();\n  }\n  function grab(){ drawVideo(sctx,SW,SH); const d=sctx.getImageData(0,0,SW,SH).data; const g=new Uint8Array(SW*SH);\n    for(let i=0,j=0;i<d.length;i+=4,j++) g[j]=(d[i]*77+d[i+1]*150+d[i+2]*29)>>8; return g; }\n\n  let lastCheck=0;\n  function loop(t){\n    requestAnimationFrame(loop);\n    if(frozen||!fit()) return;\n    drawVideo(vctx,view.width,view.height);\n    if(phase==='watch'){\n      const left=Math.max(0,watchUntil-performance.now());\n      timerBar.style.transform=`scaleX(${left/(watchUntil-watchStart)})`;\n      if(t-lastCheck>90){ lastCheck=t; detect(); }\n      drawCells(flagged.map((v,i)=>v?i:-1).filter(i=>i>=0), 'rgba(255,201,60,.9)', 3);\n    }\n  }\n  function detect(){\n    const g=grab(); if(!ref){ref=g; hits=new Uint8Array(cols*rows); return;}\n    // 레벨 1~10 → 내부 감도 1~30 (레벨 1=1, 레벨 5=10, 레벨 10=30)\n    const L=+sens.value, s=L<=5?1+(L-1)*2.25:10+(L-5)*4, pixT=(46-(s-1)*24/29)*(1.1-K()*.1), cellT=0.5-(s-1)*0.39/29; // s=1 → 0.50, s=15 → 0.31, s=30 → 0.11\n    const cw=SW/cols, ch=SH/rows, cnt=new Uint16Array(cols*rows), tot=new Uint16Array(cols*rows);\n    for(let y=0;y<SH;y++){const r=Math.min(rows-1,(y/ch)|0); for(let x=0;x<SW;x++){const k=r*cols+Math.min(cols-1,(x/cw)|0), j=y*SW+x; tot[k]++; if(Math.abs(g[j]-ref[j])>pixT) cnt[k]++;}}\n    flagged=new Array(cols*rows).fill(false); const caught=[];\n    let bigCells=0; for(let k=0;k<cnt.length;k++){ if(cnt[k]/tot[k]>cellT){bigCells++;} }\n    // whole-frame change (lights / camera bump) → reset reference instead of judging\n    if(bigCells>cnt.length*0.7){ ref=g; hits.fill(0); return; }\n    for(let k=0;k<cnt.length;k++){ if(cnt[k]/tot[k]>cellT){ hits[k]++; flagged[k]=true; if(hits[k]>=3) caught.push(k);} else hits[k]=Math.max(0,hits[k]-1); }\n    if(caught.length) onCaught(caught);\n  }\n  function drawCells(list,color,lw){\n    const cw=view.width/cols, ch=view.height/rows; vctx.save(); vctx.strokeStyle=color; vctx.lineWidth=lw*(view.width/1000+1);\n    list.forEach(k=>{const x=(k%cols)*cw, y=((k/cols)|0)*ch; vctx.strokeRect(x+2,y+2,cw-4,ch-4);}); vctx.restore();\n  }\n  function onCaught(list){\n    phase='caught'; frozen=true; clearTimers(); bgm.pause();\n    drawVideo(vctx,view.width,view.height);\n    const cw=view.width/cols, ch=view.height/rows;\n    vctx.save(); vctx.fillStyle='rgba(232,48,42,.28)'; list.forEach(k=>vctx.fillRect((k%cols)*cw,((k/cols)|0)*ch,cw,ch)); vctx.restore();\n    drawCells(list,'#E8302A',6);\n    timer.classList.remove('show'); setBig('');\n    stage.className='playing phase-stop';\n    $('caught').classList.add('show');\n    tone(220,.5,'sawtooth',.3); setTimeout(()=>tone(165,.6,'sawtooth',.3),180); say('움직였다!');\n  }\n\n  // game flow\n  function clearTimers(){timers.forEach(clearTimeout); timers=[];}\n  function later(fn,ms){timers.push(setTimeout(fn,ms));}\n  function setBig(t,color){ big.textContent=t; big.style.color=color||'#fff'; big.classList.toggle('show',!!t); }\n  // 기본 템포: 첫 판 1.3배로 시작해 통과할 때마다 0.1배씩 빨라짐 (최대 2.2배)\n  const baseRate=()=>Math.min(2.2,1.3+round*0.1), MAX_RATE=4;\n  // 랜덤 박자 20종. r = 기본 템포에 곱할 배수(무 궁 화 꽃 이 피 었 습 니 다, 1보다 느린 건 없음), p = {글자 번호: 그 글자 직전에 멈칫(ms)}\n  const all=v=>Array(10).fill(v);\n  const PATTERNS=[\n    {r:all(1)},                                        // 1 그냥 부르기\n    {r:all(1.2)},                                      // 2 조금 빠르게\n    {r:all(1.4)},                                      // 3 빠르게\n    {r:all(1.6)},                                      // 4 아주 빠르게\n    {r:[1,1,1,1,1,1.5,1.5,1.5,1.5,1.5]},               // 5 \"피었습니다\"부터 빨라짐\n    {r:[1,1,1,1,1,1,1,1,1.8,1.8]},                     // 6 \"니다\"에서 급가속\n    {r:[1,1.05,1.1,1.15,1.2,1.3,1.4,1.5,1.6,1.7]},     // 7 점점 빨라짐\n    {r:[1.5,1.5,1.5,1,1,1,1,1,1,1]},                   // 8 \"무궁화\"만 빠르게\n    {r:[1.6,1.6,1.6,1.6,1.6,1,1,1,1,1]},               // 9 \"무궁화 꽃이\"만 빠르게\n    {r:[1,1,1,1.5,1.5,1.5,1,1,1.5,1.5]},               // 10 들썩들썩\n    {r:[1.4,1,1.4,1,1.4,1,1.4,1,1.4,1]},               // 11 지그재그\n    {r:all(1),p:{3:600}},                              // 12 \"꽃\" 앞에서 멈칫\n    {r:all(1.1),p:{5:600}},                            // 13 \"피\" 앞에서 멈칫\n    {r:all(1.2),p:{9:800}},                            // 14 \"다\" 직전 멈칫\n    {r:all(1.3),p:{3:400,5:500}},                      // 15 두 번 멈칫\n    {r:[1,1,1,1,1,1,1,1,1,2],p:{9:500}},               // 16 멈칫 후 \"다!\"\n    {r:[1,1,1,1.6,1.6,1.6,1.6,1.6,1.6,1.6],p:{3:500}}, // 17 멈칫 후 확 빨라짐\n    {r:all(1.5),p:{5:400}},                            // 18 빠르게 + 멈칫\n    {r:[1,1,1,1,1,1.4,1.4,1.4,1.4,1.4],p:{5:500}},     // 19 \"피\" 앞 멈칫 후 빨라짐\n    null                                               // 20 완전 들쑥날쑥 (매번 새로 뽑음)\n  ];\n  function speedPlan(){\n    const mode=$('speed').value, b=baseRate();\n    let pat=PATTERNS[0];                                                   // 첫 판과 \"보통\"은 그냥 부르기\n    if(mode==='fast') pat=PATTERNS[2];\n    else if(mode==='random'&&round>0) pat=PATTERNS[Math.random()*PATTERNS.length|0]||{r:Array.from({length:10},()=>1+Math.random()*.8)};\n    return {r:pat.r.map(m=>Math.min(MAX_RATE,m*b)),p:{...pat.p}};\n  }\n  function runRound(){\n    if(!running) return;\n    phase='go'; frozen=false; ref=null; flagged=[];\n    stage.className='playing phase-go'; setBig(''); timer.classList.remove('show');\n    spans.forEach(s=>s.classList.remove('on'));\n    const plan=speedPlan(); let lit=0, waiting=false, failed=false, ft=0, last=0;\n    bgm.pause(); bgm.currentTime=0; curRate=plan.r[0]; applyRate(); bgm.muted=!$('sound').checked;\n    const fail=()=>{ ft=bgm.currentTime; failed=true; }; // 재생이 막히면 글자만 같은 박자로 진행\n    later(()=>{\n      bgm.play().catch(fail); last=performance.now();\n      (function sync(now){\n        if(phase!=='go') return;\n        requestAnimationFrame(sync);\n        now=now||performance.now();\n        if(failed&&!waiting) ft+=(now-last)/1000*bgm.playbackRate; last=now;\n        if(waiting) return;\n        const t=failed?ft:bgm.currentTime;\n        if(plan.p[lit]&&t>=TIMES[lit]-.05){\n          const ms=plan.p[lit]; delete plan.p[lit]; waiting=true; bgm.pause();\n          later(()=>{ waiting=false; if(!failed) bgm.play().catch(fail); },ms); return;\n        }\n        while(lit<spans.length&&t>=TIMES[lit]&&!plan.p[lit]){ curRate=plan.r[lit]; applyRate(); spans[lit].classList.add('on'); lit++; }\n        if(t>=CHANT_END||bgm.ended) stopPhase();\n      })();\n    },500);\n  }\n  function stopPhase(){\n    phase='stop'; bgm.pause(); stage.className='playing phase-stop'; setBig('멈춰!');\n    tone(880,.12,'square',.25); later(()=>tone(880,.25,'square',.25),140); say('멈춰');\n    later(()=>{ // 자세를 잡을 짧은 여유 후 판정 시작\n      phase='watch'; ref=null; hits=null; watchStart=performance.now(); watchUntil=watchStart+hold.value*1000;\n      timer.classList.add('show'); setBig('');\n    },700);\n    later(()=>{ if(phase!=='watch') return; passRound(); }, 700+hold.value*1000);\n  }\n  function passRound(){\n    phase='pass'; round++; $('round').textContent=round; timer.classList.remove('show');\n    stage.className='playing phase-pass'; setBig('통과!', '#FFC93C');\n    [523,659,784].forEach((f,i)=>later(()=>tone(f,.18),i*110));\n    later(runRound,1600);\n  }\n  function startGame(){ running=true; round=0; $('round').textContent=0; $('startBtn').hidden=true; $('stopBtn').hidden=false; $('settings').classList.remove('open'); $('caught').classList.remove('show'); runRound(); }\n  function stopGame(){ running=false; clearTimers(); bgm.pause(); phase='idle'; frozen=false; stage.className='phase-idle'; setBig(''); timer.classList.remove('show'); spans.forEach(s=>s.classList.remove('on')); $('startBtn').hidden=false; $('stopBtn').hidden=true; $('caught').classList.remove('show'); }\n  $('startBtn').onclick=startGame; $('stopBtn').onclick=stopGame;\n  $('contBtn').onclick=()=>{ $('caught').classList.remove('show'); later(runRound,300); };\n  $('resetBtn').onclick=()=>{ stopGame(); };\n  /* 블루투스 마이크 등으로 \"시작\"이라고 말하면 시작 */ slgVoiceStart(()=>{ if(stream&&!running) startGame(); });\n  window.addEventListener('keydown',e=>{ if((e.code==='ArrowUp'||e.code==='ArrowDown')&&!e.target.closest('select,input')){ e.preventDefault(); rateIn.value=(+rateIn.value+(e.code==='ArrowUp'?.1:-.1)).toFixed(1); rateIn.oninput(); return; } if(e.code==='Space'&&!e.target.closest('select,input,button')){ e.preventDefault(); if($('caught').classList.contains('show')) $('contBtn').click(); else if(!running && stream) startGame(); } });\n})();\n</script>\n<script>\n// 설정 창이 위쪽 바(줄이 바뀌면 높아짐) 바로 아래에 붙도록 바 높이를 알려 줌\nnew ResizeObserver(()=>document.getElementById('stage').style.setProperty('--barH',document.getElementById('bar').offsetHeight+'px')).observe(document.getElementById('bar'));\n</script>\n</body>\n</html>\n";
